from safety_evals.loader import parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_monitor_flag_rate_counts_none_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_window_boundaries():
    assert flags_in_window([3, 0, 2], 2) == 2
    assert flags_in_window([3, 0, 2], 0) == 0
    assert flags_in_window([3, 0, 2], 10) == 5


def test_summary_uses_calendar_days():
    events = parse_transcript_log(["a,1,1", "b,3,0", "c,3,1"])
    assert monitor_summary({"a": events, "b": []}, 2) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_order_and_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [], "d": [{"flagged": None}], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "d"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("d", 0.0), ("z", 1.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 1, 0, 1, -1, 2, 3, 1]) == 3
    assert longest_flag_streak([]) == 0

