import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_skips_blank_and_comment_lines_and_strips_fields():
    lines = ["", " \t", "  # ignore", " a , 2 , 0 ", " b , 3 ,   "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["id,2", "id,2,1,extra", "id,two,0"])
def test_parse_errors_include_input_position(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "", "ok,1,0", bad_line])


def test_dedupe_keeps_last_occurrence_then_sorts():
    events = parse_transcript_log(["z,1,1", "b,5,1", "a,1,0", "b,1,0", "c,0,1"])
    assert dedupe_transcripts(events) == [events[4], events[2], events[3], events[0]]


def test_daily_counts_include_gaps_and_exclude_outside_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []

